def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_d = 0
    opp_d = 0
    opp_c = 0
    unprovoked = 0
    provoked = 0
    accepted = 0

    for i in range(n):
        a, b = history[i]

        if a == 'D':
            my_d += 1

        if b == 'D':
            opp_d += 1
            if a == 'C':
                if i == 0 or history[i - 1][0] == 'C':
                    unprovoked += 1
                else:
                    provoked += 1
            else:
                provoked += 1
        else:
            opp_c += 1
            if a == 'D':
                accepted += 1

    start = n - 10
    if start < 0:
        start = 0

    rec_opp_d = 0
    rec_unprovoked = 0
    for i in range(start, n):
        a, b = history[i]
        if b == 'D':
            rec_opp_d += 1
            if a == 'C' and (i == 0 or history[i - 1][0] == 'C'):
                rec_unprovoked += 1

    last_a, last_b = history[-1]
    prev_a = history[-2][0] if n >= 2 else 'C'

    if opp_d == n:
        return 'D'

    if rec_unprovoked >= 3 or (unprovoked >= 4 and unprovoked > provoked):
        return 'D'

    if last_b == 'D':
        if last_a == 'C':
            if prev_a == 'D' and rec_opp_d <= 1 and unprovoked <= 2 and rec_unprovoked <= 1:
                return 'C'
            return 'D'

        if rec_unprovoked <= 1 and opp_d <= opp_c + 3 and rec_opp_d <= 1:
            return 'C'

        if rng.random() < 0.10 and rec_opp_d <= 2:
            return 'C'

        return 'D'

    if last_a == 'D':
        if opp_d == 0:
            if my_d == 1 and accepted == 1:
                return 'C'
            return 'D'

        if unprovoked <= 1 and accepted >= 2 and n >= 90:
            return 'D'

        return 'C'

    if opp_d == 0:
        if my_d > 0:
            return 'D'

        if n >= 93:
            return 'D'

        if n >= 80 and rng.random() < 0.08:
            return 'D'

        return 'C'

    if my_d > opp_d + 1:
        return 'C'

    return 'C'
